import{_t as e,it as t,n,rt as r}from"./chunks/framework.CU8IrXEP.js";var i=JSON.parse(`{"title":"实现思路","description":"","frontmatter":{"prev":{"text":"快速开始","link":"/guide/getting-started"},"next":{"text":"核心容器","link":"/guide/core"}},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md","lastUpdated":1791789379000}`),a={name:`guide/architecture.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="实现思路" tabindex="-1">实现思路 <a class="header-anchor" href="#实现思路" aria-label="Permalink to “实现思路”">​</a></h1><p>BubblesJS i18n 把国际化分成两条链路：开发时，CLI 从项目代码收集 key 并维护 JSON；运行时，core 加载 JSON、保存当前语言，React / Vue 适配层订阅变化并更新组件。JSON 是两条链路共同使用的词条格式。</p><h2 id="先看完整流程" tabindex="-1">先看完整流程 <a class="header-anchor" href="#先看完整流程" aria-label="Permalink to “先看完整流程”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>开发时：源码 tr(&quot;key&quot;) → CLI 扫描与同步 → 各语言 JSON ⇄ Excel 翻译表</span></span>
<span class="line"><span></span></span>
<span class="line"><span>运行时：默认 JSON ── message ──────► core store</span></span>
<span class="line"><span>                                      ▲</span></span>
<span class="line"><span>        其他 JSON ── loaderMessage ───┘</span></span>
<span class="line"><span>                                      │ 状态订阅</span></span>
<span class="line"><span>                              React / Vue 适配器</span></span>
<span class="line"><span>                                      │ tr(key)</span></span>
<span class="line"><span>                                   组件文本</span></span></code></pre></div><table tabindex="0"><thead><tr><th>层</th><th>包</th><th>负责的事情</th></tr></thead><tbody><tr><td>词条维护</td><td><code>@bubblesjs/i18n-cli</code></td><td>扫描项目、维护 JSON、转换 Excel 翻译表</td></tr><tr><td>翻译运行时</td><td><code>@bubblesjs/i18n-core</code></td><td>保存语言与词条、插值、异步切换、通知订阅者</td></tr><tr><td>React 接入</td><td><code>@bubblesjs/i18n-react</code></td><td>Context Provider 与外部状态订阅 Hooks</td></tr><tr><td>Vue 接入</td><td><code>@bubblesjs/i18n-vue</code></td><td>provide / inject 与响应式 Composables</td></tr></tbody></table><p>CLI 独立于运行时，也不依赖 React 或 Vue。应用可以只安装 core 与所用框架的适配器，开发环境再按需安装 CLI。</p><h2 id="词条为何使用扁平-json" tabindex="-1">词条为何使用扁平 JSON <a class="header-anchor" href="#词条为何使用扁平-json" aria-label="Permalink to “词条为何使用扁平 JSON”">​</a></h2><p>词条使用 <code>Record&lt;string, string&gt;</code>：源码中的 key、JSON 的键和 Excel 的 key 列共享同一种标识，扫描去重和运行时查找都可以直接比较字符串。<code>menu.home</code> 是完整的键，不展开成嵌套路径；也可以使用中文原文作为 key。</p><p>可直接使用的语言包示例见<a href="./getting-started#准备语言-json">快速开始</a>。</p><h2 id="cli-如何把项目扫描成-json" tabindex="-1">CLI 如何把项目扫描成 JSON <a class="header-anchor" href="#cli-如何把项目扫描成-json" aria-label="Permalink to “CLI 如何把项目扫描成 JSON”">​</a></h2><ol><li>按配置中的 <code>include</code> / <code>exclude</code> 枚举源码，以 <code>callNames</code> 匹配调用并记录 key 的文件、行和列。</li><li>每个项目去重 key，与各语言 JSON 比较，生成差异计划。</li><li><code>sync</code> 写入缺失 key，保留已有译文；<code>check</code> 只检查差异并返回退出码。</li></ol><p>扫描器使用文本匹配，不解析完整 AST，也不执行源码；同步不会自动翻译。命令、扫描限制和写入规则见 <a href="./cli">CLI 使用</a>。</p><h2 id="core-如何翻译和切换语言" tabindex="-1">core 如何翻译和切换语言 <a class="header-anchor" href="#core-如何翻译和切换语言" aria-label="Permalink to “core 如何翻译和切换语言”">​</a></h2><p>core 使用自建的可订阅容器，通过 <code>getState()</code>、<code>setState()</code> 和 <code>subscribe()</code> 管理状态：</p><ul><li><code>tr</code> 每次读取最新的 <code>message</code>，查找 key 后交给 <code>formatMessage</code> 插值。</li><li><code>loadLocale</code> 调用应用提供的加载器，完成后一次提交 <code>locale</code> 和 <code>message</code>，再通知订阅者。</li><li>请求使用递增编号，较早请求的结果不会覆盖较晚的语言选择。</li></ul><p>资源加载与缓存由应用实现；core 负责状态和翻译。初始化方式、失败处理和持久化见<a href="./core">核心容器</a>。</p><h2 id="react-与-vue-如何更新组件" tabindex="-1">React 与 Vue 如何更新组件 <a class="header-anchor" href="#react-与-vue-如何更新组件" aria-label="Permalink to “React 与 Vue 如何更新组件”">​</a></h2><p>两个适配器都接收同一种 core store，不重复实现翻译规则：</p><table tabindex="0"><thead><tr><th>过程</th><th>React</th><th>Vue</th></tr></thead><tbody><tr><td>向组件树提供容器</td><td><code>I18nProvider</code> / Context</td><td><code>I18nProvider</code> / provide</td></tr><tr><td>在子组件取得容器</td><td>Context</td><td>inject</td></tr><tr><td>订阅状态变化</td><td><code>useSyncExternalStore</code></td><td><code>shallowRef</code> 保存状态快照</td></tr><tr><td>暴露组件可用值</td><td><code>useI18n()</code> 返回翻译方法、切换方法和当前语言</td><td><code>useI18n()</code> 返回翻译方法、切换方法和 computed 语言引用</td></tr><tr><td>清理订阅</td><td>React 订阅生命周期</td><td><code>onScopeDispose</code></td></tr></tbody></table><p>Vue 的 <code>tr</code> 包装函数读取响应式快照，在模板或 computed 中调用时建立依赖；React 通过外部状态订阅触发重新渲染。切换语言的路径是：<strong>组件调用 <code>loadLocale</code> → core 更新状态 → 适配器收到通知 → 组件更新译文</strong>。</p><p>具体接入见 <a href="./react">React</a>和 <a href="./vue">Vue</a>，多个容器的隔离规则见<a href="./scopes">全局与局部使用</a>。</p><h2 id="json-⇄-excel-如何协作" tabindex="-1">JSON ⇄ Excel 如何协作 <a class="header-anchor" href="#json-⇄-excel-如何协作" aria-label="Permalink to “JSON ⇄ Excel 如何协作”">​</a></h2><p>Excel 中每行是一个 key，每个语言占一列。CLI 导出 JSON 供译者填写，再将译文导入回 JSON；应用始终加载 JSON，Excel 只参与开发时的维护。</p><p>转换直接比较两端当前值，不依赖历史同步记录。配置、表结构与冲突规则见 <a href="./cli#excel-workflow">CLI 工作流</a>。</p><h2 id="对照源码阅读" tabindex="-1">对照源码阅读 <a class="header-anchor" href="#对照源码阅读" aria-label="Permalink to “对照源码阅读”">​</a></h2><table tabindex="0"><thead><tr><th>实现</th><th>源码入口</th></tr></thead><tbody><tr><td>状态、翻译与语言加载</td><td><a href="https://github.com/bubblesplant/i18n/blob/main/packages/i18n-core/src/i18n.ts" target="_blank" rel="noreferrer">core / i18n.ts</a>、<a href="https://github.com/bubblesplant/i18n/blob/main/packages/i18n-core/src/store.ts" target="_blank" rel="noreferrer">store.ts</a></td></tr><tr><td>React 订阅</td><td><a href="https://github.com/bubblesplant/i18n/blob/main/packages/i18n-react/src/index.tsx" target="_blank" rel="noreferrer">react / index.tsx</a>、<a href="https://github.com/bubblesplant/i18n/blob/main/packages/i18n-react/src/use-store.ts" target="_blank" rel="noreferrer">use-store.ts</a></td></tr><tr><td>Vue 响应式订阅</td><td><a href="https://github.com/bubblesplant/i18n/blob/main/packages/i18n-vue/src/index.ts" target="_blank" rel="noreferrer">vue / index.ts</a>、<a href="https://github.com/bubblesplant/i18n/blob/main/packages/i18n-vue/src/use-store.ts" target="_blank" rel="noreferrer">use-store.ts</a></td></tr><tr><td>扫描与 JSON 同步</td><td><a href="https://github.com/bubblesplant/i18n/blob/main/packages/i18n-cli/src/scanner.ts" target="_blank" rel="noreferrer">cli / scanner.ts</a>、<a href="https://github.com/bubblesplant/i18n/blob/main/packages/i18n-cli/src/sync.ts" target="_blank" rel="noreferrer">sync.ts</a></td></tr></tbody></table>`,26)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};